; SEEK8 / SEEK16 movement kernels for v2_pareto_fast.
;
; GENERATED by tools/generate_seek_sources.py from tools/seek_kernel.py;
; routines/movement/seek_u8_u8_dda.asm and seek_u16_u8_dda.asm are the same
; kernels with a standalone IO block.
;
; MATH_SEEK8_*: x and y are unsigned bytes. MATH_SEEK16_*: x is unsigned 16-bit
; (|dx| <= 32767), y an unsigned byte.
;
; Speed: MATH-style Q8.8 pixels per frame. SPL = fraction, SPH bits 0-6 =
; integer part (0..126). SPH bit 7 selects the speed meaning:
;   0  speed along the MAJOR axis (classic Bresenham: a 45 degree move covers
;      sqrt(2) x the distance per frame)
;   1  speed along the path (constant Euclidean speed, within 0.7%)
;
; Every frame's position is on the Bresenham line from the start to the target
; (within 0.5 px of the true line) and the object lands exactly on the target.
; Each frame moves the major axis by k = floor or ceil of the speed and the
; minor axis by the exact Bresenham amount for k pixels, precomputed at init as
; k*dmin = whole_k*dmaj + rem_k. One counter R = dmaj*256 - 1 - speeds so far
; carries both the speed fraction (borrow out of its low byte: this frame moves
; k0+1) and the distance (borrow out of the top: arrival).
;
; X = slot (0..7) for every entry and is preserved; A/Y are volatile; D=0 is
; required. The start position is whatever POS_* holds for the slot. The
; steppers return C=1 on the frame the target is reached and on every later
; call (the position stays on the target), else C=0; they use no scratch.
; Init returns C=1 if the object is already on the target, else C=0.
; Use one stepper per move: STEP (any speed), STEP_INT (major-axis integer
; speed >= 1 with bit 7 clear; ignores the fraction) or STEP1 (init with speed
; $0100; exactly 1 px/frame; uses NMOS DCP).
;
; Inputs (preserved): MATH_X+0 = target x (MATH_X+1 = high byte for SEEK16),
; MATH_Y+0 = target y, MATH_N+0 = speed fraction, MATH_N+1 = speed integer
; with bit 7 selecting Euclidean speed.
; Object state: MATH_SEEK8_POS_X/MATH_SEEK8_POS_Y and MATH_SEEK16_POS_XL/
; MATH_SEEK16_POS_XH/MATH_SEEK16_POS_Y, indexed by slot.
;
; Scratch is ZP_MAIN+$51.. (the V2-V4 game scratch ZP).
; Init scratch: 19 bytes at SEEK_T, inside the profile's game scratch.
; This file owns the eight public JMP slots at REG_GAME_API+$003C..+$0053 and
; is included after the generated resident body.

SEEK_IN_X   = MATH_IO+$00
SEEK_IN_XH  = MATH_IO+$01
SEEK_IN_Y   = MATH_IO+$04
SEEK_IN_SPL = MATH_IO+$10
SEEK_IN_SPH = MATH_IO+$11
SEEK_T      = ZP_MAIN+$51
SK_EMAJ   = SEEK_T+0
SK_EMIN   = SEEK_T+1
SK_Q      = SEEK_T+2
SK_PH     = SEEK_T+3
SK_SPH    = SEEK_T+4
SK_MX     = SEEK_T+5
SK_MY     = SEEK_T+6
SK_MODE   = SEEK_T+7
SK_WHOLE  = SEEK_T+8
SK_UN     = SEEK_T+9
SK_SGN    = SEEK_T+10
SK_VMAJ   = SEEK_T+11
SK_T      = SEEK_T+12
SK_DMAJL  = SEEK_T+13
SK_DMAJH  = SEEK_T+14
SK_DMIN   = SEEK_T+15
SK_REML   = SEEK_T+16
SK_REMH   = SEEK_T+17
SK_REM8   = SEEK_T+18

SEEK8_STATE  = REG_API+$0A90
SEEK16_STATE = REG_TABLE+$30E8
S8_POS_X   = SEEK8_STATE+0
S8_POS_Y   = SEEK8_STATE+8
S8_TGT_X   = SEEK8_STATE+16
S8_TGT_Y   = SEEK8_STATE+24
S8_RL      = SEEK8_STATE+32
S8_RH      = SEEK8_STATE+40
S8_ERR     = SEEK8_STATE+48
S8_DMAJ    = SEEK8_STATE+56
S8_KF      = SEEK8_STATE+64
S8_KI      = SEEK8_STATE+72
S8_REM     = SEEK8_STATE+80
S8_VX      = SEEK8_STATE+96
S8_VY      = SEEK8_STATE+128
S16_POS_XL  = SEEK16_STATE+0
S16_POS_XH  = SEEK16_STATE+8
S16_POS_Y   = SEEK16_STATE+16
S16_TGT_XL  = SEEK16_STATE+24
S16_TGT_XH  = SEEK16_STATE+32
S16_TGT_Y   = SEEK16_STATE+40
S16_RL      = SEEK16_STATE+48
S16_RM      = SEEK16_STATE+56
S16_RH      = SEEK16_STATE+64
S16_ERRL    = SEEK16_STATE+72
S16_ERRH    = SEEK16_STATE+80
S16_DMAJL   = SEEK16_STATE+88
S16_DMAJH   = SEEK16_STATE+96
S16_KF      = SEEK16_STATE+104
S16_KI      = SEEK16_STATE+112
S16_REML    = SEEK16_STATE+120
S16_REMH    = SEEK16_STATE+136
S16_VXL     = SEEK16_STATE+152
S16_VXH     = SEEK16_STATE+184
S16_VY      = SEEK16_STATE+216

; Stable public JMP slots.
* = REG_GAME_API+$003C

    jmp seek8_init        ; MATH_SEEK8_INIT
    jmp seek8_step        ; MATH_SEEK8_STEP
    jmp seek8_step_int    ; MATH_SEEK8_STEP_INT
    jmp seek8_step1       ; MATH_SEEK8_STEP1
    jmp seek16_init       ; MATH_SEEK16_INIT
    jmp seek16_step       ; MATH_SEEK16_STEP
    jmp seek16_step_int   ; MATH_SEEK16_STEP_INT
    jmp seek16_step1      ; MATH_SEEK16_STEP1

* = REG_API+$0E00
; ---- SEEK8 per-frame steppers ----
seek8_step:
        lda S8_RL,x             ; R -= speed; low borrow: this frame moves k0+1
        sec
        sbc S8_KF,x
        sta S8_RL,x
        bcc s8_set1
seek8_step_int:
        sec
        lda S8_RH,x             ; k0 frame (also the integer stepper)
        sbc S8_KI,x
        sta S8_RH,x
        bcc s8_arrive
s8_move0:
        lda S8_ERR,x            ; C=1: err -= rem_k
        sbc S8_REM,x
        bcc s8_wrap0
        sta S8_ERR,x
        lda S8_POS_X,x          ; C=1 into VX; VY absorbs the carry out
        adc S8_VX,x
        sta S8_POS_X,x
        lda S8_POS_Y,x
        adc S8_VY,x
        sta S8_POS_Y,x
        clc
        rts
s8_wrap0:
        adc S8_DMAJ,x           ; err += dmaj; the true sum is >= 0, so C=1
        sta S8_ERR,x
        lda S8_POS_X,x
        adc S8_VX+16,x
        sta S8_POS_X,x
        lda S8_POS_Y,x
        adc S8_VY+16,x
        sta S8_POS_Y,x
        clc
        rts
seek8_step1:
        lda #$FF                ; DCP: RH -= 1 and compare with $FF in one go.
        !byte $DF, <S8_RH, >S8_RH    ; DCP S8_RH,X
        bne s8_move0            ; Z=1 only when RH wrapped (arrival); C=1
s8_arrive:
        lda S8_TGT_X,x          ; land exactly on the target
        sta S8_POS_X,x
        lda S8_TGT_Y,x
        sta S8_POS_Y,x
s8_arrived:
        lda #0                  ; R = 0 and k0 = 1: every later call borrows
        sta S8_RH,x             ; out of RH and snaps again
        lda #1
        sta S8_KI,x
        sec
        rts
s8_set1:
        lda S8_RH,x             ; C=0: subtracts k0+1
        sbc S8_KI,x
        sta S8_RH,x
        bcc s8_arrive
        lda S8_ERR,x
        sbc S8_REM+8,x
        bcc s8_wrap1
        sta S8_ERR,x
        lda S8_POS_X,x
        adc S8_VX+8,x
        sta S8_POS_X,x
        lda S8_POS_Y,x
        adc S8_VY+8,x
        sta S8_POS_Y,x
        clc
        rts
s8_wrap1:
        adc S8_DMAJ,x
        sta S8_ERR,x
        lda S8_POS_X,x
        adc S8_VX+24,x
        sta S8_POS_X,x
        lda S8_POS_Y,x
        adc S8_VY+24,x
        sta S8_POS_Y,x
        clc
        rts

* = REG_LOW+$0B00
; ---- SEEK8 init ----
seek8_init:
        lda #$FF
        sta S8_RL,x
        ldy #0
        lda SEEK_IN_Y
        sta S8_TGT_Y,x
        sec
        sbc S8_POS_Y,x
        bcs s8i_dy
        eor #$FF
        adc #1                  ; C=0
        dey
s8i_dy:
        sta SK_EMIN
        sty SK_MY
        ldy #0
        lda SEEK_IN_X
        sta S8_TGT_X,x
        sec
        sbc S8_POS_X,x
        bcs s8i_dx
        eor #$FF
        adc #1
        dey
s8i_dx:
        sty SK_MX
        cmp SK_EMIN
        bcs s8i_xmaj
        ldy SK_EMIN             ; y major: dmaj = |dy|, dmin = |dx|
        sta SK_EMIN
        lda SK_MX
        ora #1
        sta SK_UN               ; minor unit = x direction
        tya
        ldy #$80
        bne s8i_mode
s8i_xmaj:
        tay
        lda SK_MY
        ora #1
        sta SK_UN               ; minor unit = y direction
        tya
        ldy #0
s8i_mode:
        sty SK_MODE
        sta SK_EMAJ
        sta S8_DMAJ,x
        lsr
        sta S8_ERR,x            ; err = dmaj/2
        lda SK_EMAJ
        sec
        sbc #1
        sta S8_RH,x             ; RH:RL = dmaj*256-1
        bcc s8i_zero
        lda SEEK_IN_SPH
        bmi s8i_euclid
        sta S8_KI,x
        lda SEEK_IN_SPL
        sta S8_KF,x
s8i_rates:
        lda #0                  ; rem0 = k0*dmin mod dmaj, whole0 = div
        sta SK_WHOLE
        ldy S8_KI,x
        beq s8i_r0done
s8i_r0:
        clc
        adc SK_EMIN
        bcs s8i_r0sub
        cmp SK_EMAJ
        bcc s8i_r0next
s8i_r0sub:
        sbc SK_EMAJ             ; C=1 on both paths
        inc SK_WHOLE
s8i_r0next:
        dey
        bne s8i_r0
s8i_r0done:
        sta S8_REM,x
        sta SK_REM8
        txa
        tay                     ; planes for k0 at Y = slot
        lda S8_KI,x
        jsr s8_planes
        lda S8_KF,x             ; integer speed: the k0+1 planes are never used
        beq s8i_done
        lda SK_REM8             ; rem1 = rem0 + dmin (at most one more wrap)
        clc
        adc SK_EMIN
        bcs s8i_r1sub
        cmp SK_EMAJ
        bcc s8i_r1done
s8i_r1sub:
        sbc SK_EMAJ
        inc SK_WHOLE
s8i_r1done:
        sta S8_REM+8,x
        txa
        ora #8                  ; Y = slot+8 (slot < 8)
        tay
        lda S8_KI,x
        sec
        adc #0                  ; k0+1
        jsr s8_planes
s8i_done:
        clc
        rts
s8i_zero:
        jmp s8_arrived          ; C=1
s8i_euclid:
        jsr seek_euclid_speed   ; A = integer, Y = fraction
        sta S8_KI,x
        tya
        sta S8_KF,x
        jmp s8i_rates

* = REG_GAME_API+$0054
; ---- SEEK16 per-frame steppers ----
seek16_step1:
        lda #$FF
        !byte $DF, <S16_RM, >S16_RM  ; DCP S16_RM,X
        bne s16_move0           ; C=1
        !byte $DF, <S16_RH, >S16_RH  ; DCP S16_RH,X: RM wrapped, borrow up
        bne s16_move0           ; Z=1 only when RH wrapped (arrival)
s16_arrive:
        lda S16_TGT_XL,x        ; land exactly on the target
        sta S16_POS_XL,x
        lda S16_TGT_XH,x
        sta S16_POS_XH,x
        lda S16_TGT_Y,x
        sta S16_POS_Y,x
s16_arrived:
        lda #0                  ; R = 0 and k0 = 1: every later call borrows
        sta S16_RM,x            ; out of RH and snaps again
        sta S16_RH,x
        lda #1
        sta S16_KI,x
        sec
        rts
s16_borrow0:                    ; RM borrowed: take it from RH (rare)
        dec S16_RH,x
        bmi s16_arrive
        sec
        jmp s16_move0
seek16_step:
        lda S16_RL,x            ; R -= speed; low borrow: this frame moves k0+1
        sec
        sbc S16_KF,x
        sta S16_RL,x
        bcc s16_set1
seek16_step_int:
        sec
        lda S16_RM,x
        sbc S16_KI,x
        sta S16_RM,x
        bcc s16_borrow0
s16_move0:
        lda S16_ERRL,x          ; C=1: err -= rem_k (16-bit)
        sbc S16_REML,x
        sta S16_ERRL,x
        lda S16_ERRH,x
        sbc S16_REMH,x
        bcc s16_wrap0
        sta S16_ERRH,x
        lda S16_POS_XL,x        ; C=1 into VX; VY absorbs the carry out
        adc S16_VXL,x
        sta S16_POS_XL,x
        lda S16_POS_XH,x
        adc S16_VXH,x
        sta S16_POS_XH,x
        lda S16_POS_Y,x
        adc S16_VY,x
        sta S16_POS_Y,x
        clc
        rts
s16_wrap0:
        tay                     ; err += dmaj
        lda S16_ERRL,x
        adc S16_DMAJL,x
        sta S16_ERRL,x
        tya
        adc S16_DMAJH,x
        sta S16_ERRH,x          ; C=1
        lda S16_POS_XL,x
        adc S16_VXL+16,x
        sta S16_POS_XL,x
        lda S16_POS_XH,x
        adc S16_VXH+16,x
        sta S16_POS_XH,x
        lda S16_POS_Y,x
        adc S16_VY+16,x
        sta S16_POS_Y,x
        clc
        rts
s16_set1:
        lda S16_RM,x            ; C=0: subtracts k0+1
        sbc S16_KI,x
        sta S16_RM,x
        bcc s16_borrow1
s16_move1:
        lda S16_ERRL,x
        sbc S16_REML+8,x
        sta S16_ERRL,x
        lda S16_ERRH,x
        sbc S16_REMH+8,x
        bcc s16_wrap1
        sta S16_ERRH,x
        lda S16_POS_XL,x
        adc S16_VXL+8,x
        sta S16_POS_XL,x
        lda S16_POS_XH,x
        adc S16_VXH+8,x
        sta S16_POS_XH,x
        lda S16_POS_Y,x
        adc S16_VY+8,x
        sta S16_POS_Y,x
        clc
        rts
s16_wrap1:
        tay
        lda S16_ERRL,x
        adc S16_DMAJL,x
        sta S16_ERRL,x
        tya
        adc S16_DMAJH,x
        sta S16_ERRH,x
        lda S16_POS_XL,x
        adc S16_VXL+24,x
        sta S16_POS_XL,x
        lda S16_POS_XH,x
        adc S16_VXH+24,x
        sta S16_POS_XH,x
        lda S16_POS_Y,x
        adc S16_VY+24,x
        sta S16_POS_Y,x
        clc
        rts
s16_borrow1:                    ; RM borrowed: take it from RH (rare)
        dec S16_RH,x
        bpl s16_b1ok
        jmp s16_arrive
s16_b1ok:
        sec
        jmp s16_move1

* = REG_LOW+$08E2
; ---- SEEK16 init ----
seek16_init:
        lda #$FF
        sta S16_RL,x
        ldy #0
        lda SEEK_IN_Y
        sta S16_TGT_Y,x
        sec
        sbc S16_POS_Y,x
        bcs s16i_dy
        eor #$FF
        adc #1                  ; C=0
        dey
s16i_dy:
        sta SK_DMIN
        sty SK_MY
        ldy #0
        lda SEEK_IN_X
        sta S16_TGT_XL,x
        sec
        sbc S16_POS_XL,x
        sta SK_DMAJL
        lda SEEK_IN_XH
        sta S16_TGT_XH,x
        sbc S16_POS_XH,x
        bcs s16i_dx
        eor #$FF                ; |dx| = ~dx + 1; C=0 here
        sta SK_DMAJH
        lda SK_DMAJL
        eor #$FF
        adc #1
        sta SK_DMAJL
        bcc s16i_dxn
        inc SK_DMAJH
s16i_dxn:
        dey
        lda SK_DMAJH
s16i_dx:
        sta SK_DMAJH
        sty SK_MX
        bne s16i_xmaj           ; |dx| >= 256 > |dy|
        lda SK_DMAJL
        cmp SK_DMIN
        bcs s16i_xmaj
        ldy SK_DMIN             ; y major: dmaj = |dy|, dmin = |dx|
        sta SK_DMIN
        sty SK_DMAJL
        lda SK_MX
        ora #1
        sta SK_UN
        lda #$80
        bne s16i_mode
s16i_xmaj:
        lda SK_MY
        ora #1
        sta SK_UN
        lda #0
s16i_mode:
        sta SK_MODE
        lda SK_DMAJH
        sta S16_DMAJH,x
        lsr
        sta S16_ERRH,x          ; err = dmaj/2
        lda SK_DMAJL
        sta S16_DMAJL,x
        ror
        sta S16_ERRL,x
        lda SK_DMAJL            ; RH:RM:RL = dmaj*256-1
        sec
        sbc #1
        sta S16_RM,x
        lda SK_DMAJH
        sbc #0
        sta S16_RH,x
        bcc s16i_zero
        lda SEEK_IN_SPH
        bmi s16i_euclid
        sta S16_KI,x
        lda SEEK_IN_SPL
        sta S16_KF,x
s16i_rates:
        lda #0                  ; rem0 = k0*dmin mod dmaj (16-bit)
        sta SK_REML
        sta SK_REMH
        sta SK_WHOLE
        ldy S16_KI,x
        beq s16i_r0done
s16i_r0:
        jsr s16_addmin
        dey
        bne s16i_r0
s16i_r0done:
        lda SK_REML
        sta S16_REML,x
        lda SK_REMH
        sta S16_REMH,x
        txa
        tay
        lda S16_KI,x
        jsr s16_planes
        lda S16_KF,x
        beq s16i_done
        jsr s16_addmin          ; k0+1
        lda SK_REML
        sta S16_REML+8,x
        lda SK_REMH
        sta S16_REMH+8,x
        txa
        ora #8
        tay
        lda S16_KI,x
        sec
        adc #0
        jsr s16_planes
s16i_done:
        clc
        rts
s16i_zero:
        jmp s16_arrived         ; C=1
s16i_euclid:
        lda SK_DMAJH            ; scale dmaj below 256 for an 8-bit ratio
        sta SK_T
        lda SK_DMIN
        sta SK_EMIN
        lda SK_DMAJL
        ldy SK_T
s16i_scale:
        beq s16i_scaled
        lsr SK_T
        ror
        lsr SK_EMIN
        ldy SK_T
        jmp s16i_scale
s16i_scaled:
        sta SK_EMAJ
        jsr seek_euclid_speed   ; A = integer, Y = fraction
        sta S16_KI,x
        tya
        sta S16_KF,x
        jmp s16i_rates

* = REG_API+$0F6C
; ---- SEEK8 plane writer ----
; A = k, SK_WHOLE = whole, Y = plane index (slot or slot+8). Writes the
; no-wrap plane at Y and the wrap plane at Y+16.
; Stored values: VX = vx-1 (added with C=1) and VY = vy + sign(VX), which
; absorbs the carry out of the x add.
s8_planes:
        bit SK_MODE
        bmi s8p_ymaj
        eor SK_MX               ; x major: VX = (k eor m) - m - 1
        clc
        sbc SK_MX
        sta S8_VX,y
        sta S8_VX+16,y
        ora #$7F
        bmi s8p_xs
        lda #0
s8p_xs:
        sta SK_SGN
        lda SK_WHOLE            ; vy = (whole eor m) - m
        eor SK_MY
        sec
        sbc SK_MY
        clc
        adc SK_SGN
        sta S8_VY,y
        clc
        adc SK_UN               ; wrap: one more minor step
        sta S8_VY+16,y
        rts
s8p_ymaj:
        eor SK_MY               ; y major: vy = (k eor m) - m
        sec
        sbc SK_MY
        sta SK_VMAJ
        lda SK_WHOLE            ; VX = (whole eor m) - m - 1
        eor SK_MX
        clc
        sbc SK_MX
        sta S8_VX,y
        sta SK_T
        ora #$7F
        bmi s8p_y0
        lda #0
s8p_y0:
        clc
        adc SK_VMAJ
        sta S8_VY,y
        lda SK_T                ; wrap: VX + unit
        clc
        adc SK_UN
        sta S8_VX+16,y
        ora #$7F
        bmi s8p_y1
        lda #0
s8p_y1:
        clc
        adc SK_VMAJ
        sta S8_VY+16,y
        rts

* = REG_API+$0EE3
; ---- SEEK16 helpers ----
; rem += dmin; if rem >= dmaj: rem -= dmaj, whole++.  Preserves X/Y.
s16_addmin:
        lda SK_REML
        clc
        adc SK_DMIN
        sta SK_REML
        bcc s16a_nc
        inc SK_REMH
s16a_nc:
        cmp SK_DMAJL
        lda SK_REMH
        sbc SK_DMAJH
        bcc s16a_done
        sta SK_REMH
        lda SK_REML
        sbc SK_DMAJL
        sta SK_REML
        inc SK_WHOLE
s16a_done:
        rts

; As s8_planes, with a 16-bit x delta: VXH is the sign byte of VX.
s16_planes:
        bit SK_MODE
        bmi s16p_ymaj
        eor SK_MX
        clc
        sbc SK_MX
        sta S16_VXL,y
        sta S16_VXL+16,y
        ora #$7F
        bmi s16p_xs
        lda #0
s16p_xs:
        sta S16_VXH,y
        sta S16_VXH+16,y
        sta SK_SGN
        lda SK_WHOLE
        eor SK_MY
        sec
        sbc SK_MY
        clc
        adc SK_SGN
        sta S16_VY,y
        clc
        adc SK_UN
        sta S16_VY+16,y
        rts
s16p_ymaj:
        eor SK_MY
        sec
        sbc SK_MY
        sta SK_VMAJ
        lda SK_WHOLE
        eor SK_MX
        clc
        sbc SK_MX
        sta S16_VXL,y
        sta SK_T
        ora #$7F
        bmi s16p_y0
        lda #0
s16p_y0:
        sta S16_VXH,y
        clc
        adc SK_VMAJ
        sta S16_VY,y
        lda SK_T
        clc
        adc SK_UN
        sta S16_VXL+16,y
        ora #$7F
        bmi s16p_y1
        lda #0
s16p_y1:
        sta S16_VXH+16,y
        clc
        adc SK_VMAJ
        sta S16_VY+16,y
        rts

* = REG_API+$0D23
; ---- shared: Euclidean speed -> major-axis speed ----
; In: SK_EMAJ >= 1 and SK_EMIN <= SK_EMAJ (8-bit magnitudes), speed in
; SEEK_IN_SPL/SEEK_IN_SPH (bit 7 ignored). Out: A = integer, Y = fraction of
; speed*cos(atan(dmin/dmaj)) = speed - (speed*d >> 8), d = seek_cos_d[q],
; q = min(31, floor(32*dmin/dmaj)). Preserves X.
seek_euclid_speed:
        lda SEEK_IN_SPH
        and #$7F
        sta SK_SPH
        lda #$08                ; quotient sentinel: 5 rols push it into C
        sta SK_Q
        lda SK_EMIN
seu_div:
        asl
        bcs seu_sub
        cmp SK_EMAJ
        bcc seu_skip
seu_sub:
        sbc SK_EMAJ
        sec
seu_skip:
        rol SK_Q
        bcc seu_div
        ldy SK_Q
        lda #0
        sta SK_PH
        lda seek_cos_d,y        ; d leaves LSB first; the sentinel in bit 7
        sec                     ; ends the loop after 8 shifts
        ror
        sta SK_Q
        lda #0
seu_mul:
        bcc seu_mskip
        clc
        adc SEEK_IN_SPL
        tay
        lda SK_PH
        adc SK_SPH
        sta SK_PH
        tya
seu_mskip:
        ror SK_PH
        ror
        lsr SK_Q
        bne seu_mul
        sta SK_Q                ; speed - P
        lda SEEK_IN_SPL
        sec
        sbc SK_Q
        tay
        lda SK_SPH
        sbc SK_PH
        rts

; cos_d[q] = round(256*(1-cos(atan((q+0.5)/32))))
seek_cos_d:
        !byte 0, 0, 1, 2, 2, 4, 5, 7
        !byte 9, 11, 13, 15, 18, 20, 23, 26
        !byte 28, 31, 34, 37, 40, 44, 47, 50
        !byte 53, 56, 59, 62, 65, 68, 71, 74
